<?php
$appPage='profile';$appTitle='Profile & security';require __DIR__.'/../includes/customer_header.php';$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{requireCsrf();$action=$_POST['action']??'';if($action==='profile'){$name=trim($_POST['full_name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$occupation=trim($_POST['occupation']??'');if(!$email||mb_strlen($name)<2||mb_strlen($phone)<7||mb_strlen($address)<5)throw new InvalidArgumentException('Complete each required profile field with valid information.');$stmt=$pdo->prepare('UPDATE users SET full_name=?,email=?,phone=?,address=?,occupation=? WHERE user_id=?');$stmt->execute([mb_substr($name,0,100),$email,mb_substr($phone,0,20),mb_substr($address,0,1000),mb_substr($occupation,0,50),$customerId]);audit($pdo,'profile.updated','user',$customerId);$notice='Profile information updated.';}elseif($action==='password'){$current=$_POST['current_password']??'';$password=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';$stmt=$pdo->prepare('SELECT password_hash FROM users WHERE user_id=?');$stmt->execute([$customerId]);if(!password_verify($current,(string)$stmt->fetchColumn()))throw new RuntimeException('Current password is incorrect.');if($password!==$confirm||!validatePassword($password))throw new InvalidArgumentException('Use at least eight characters with uppercase, lowercase, a number, and a symbol.');$pdo->prepare('UPDATE users SET password_hash=?,session_version=session_version+1 WHERE user_id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$customerId]);$pdo->prepare("INSERT INTO security_events(user_id,event_type,ip_address,user_agent) VALUES(?,'password_changed',?,?)")->execute([$customerId,clientIp(),substr($_SERVER['HTTP_USER_AGENT']??'',0,255)]);regenerateSession();$_SESSION['session_version']=(int)($_SESSION['session_version']??1)+1;$notice='Password changed and other sessions invalidated.';}elseif($action==='avatar'){if(!isset($_FILES['avatar'])||$_FILES['avatar']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Choose an image to upload.');$file=$_FILES['avatar'];if($file['size']>2*1024*1024)throw new InvalidArgumentException('Image must be 2 MB or smaller.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$extensions=['image/jpeg'=>'jpg','image/png'=>'png'];if(!isset($extensions[$mime]))throw new InvalidArgumentException('Only JPEG and PNG images are accepted.');$directory=__DIR__.'/../uploads/avatars';if(!is_dir($directory)&&!mkdir($directory,0750,true))throw new RuntimeException('Upload storage is unavailable.');$name=bin2hex(random_bytes(20)).'.'.$extensions[$mime];if(!move_uploaded_file($file['tmp_name'],$directory.'/'.$name))throw new RuntimeException('Upload could not be stored.');$stmt=$pdo->prepare('SELECT profile_picture FROM users WHERE user_id=?');$stmt->execute([$customerId]);$old=$stmt->fetchColumn();$pdo->prepare('UPDATE users SET profile_picture=? WHERE user_id=?')->execute(['avatars/'.$name,$customerId]);if(is_string($old)&&str_starts_with($old,'avatars/')){$oldPath=realpath(__DIR__.'/../uploads/'.$old);$root=realpath(__DIR__.'/../uploads/avatars');if($oldPath&&$root&&str_starts_with($oldPath,$root.DIRECTORY_SEPARATOR))unlink($oldPath);}audit($pdo,'profile.avatar_updated','user',$customerId);$notice='Profile image updated.';}}catch(Throwable $e){$error=$e->getMessage();}}
$stmt=$pdo->prepare('SELECT u.*,a.account_number FROM users u LEFT JOIN accounts a ON a.user_id=u.user_id WHERE u.user_id=?');$stmt->execute([$customerId]);$user=$stmt->fetch();$logins=$pdo->prepare('SELECT ip_address,user_agent,status,login_time FROM login_records WHERE user_id=? ORDER BY login_time DESC LIMIT 8');$logins->execute([$customerId]);
?>
<?php if($notice):?><div class="notice success"><?=e($notice)?></div><?php endif?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><div class="app-grid"><section class="panel span-7"><h2>Personal details</h2><p class="muted">Keep your contact information accurate. Identity changes may require another review.</p><form method="post" class="form-grid"><?=csrfField()?><input type="hidden" name="action" value="profile"><div class="field"><label>Full name</label><input name="full_name" value="<?=e($user['full_name'])?>" maxlength="100" required></div><div class="field"><label>Email</label><input type="email" name="email" value="<?=e($user['email'])?>" required></div><div class="field"><label>Phone</label><input name="phone" value="<?=e($user['phone'])?>" maxlength="20" required></div><div class="field"><label>Occupation</label><input name="occupation" value="<?=e($user['occupation'])?>" maxlength="50"></div><div class="field full"><label>Residential address</label><textarea name="address" maxlength="1000" required><?=e($user['address'])?></textarea></div><button class="button button-primary">Save details</button></form></section><section class="panel span-5"><h2>Account identity</h2><div class="detail-grid"><div><span>Account number</span><strong><?=e($user['account_number']??'—')?></strong></div><div><span>KYC status</span><strong><?=e(str_replace('_',' ',$user['kyc_status']))?></strong></div><div><span>Customer since</span><strong><?=e(date('M Y',strtotime($user['created_at'])))?></strong></div></div><h3>Profile image</h3><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrfField()?><input type="hidden" name="action" value="avatar"><div class="field full"><label>JPEG or PNG, up to 2 MB</label><input type="file" name="avatar" accept="image/jpeg,image/png" required></div><button class="button button-secondary">Upload image</button></form></section><section class="panel span-5"><h2>Change password</h2><form method="post" class="form-grid"><?=csrfField()?><input type="hidden" name="action" value="password"><div class="field full"><label>Current password</label><input type="password" name="current_password" autocomplete="current-password" required></div><div class="field full"><label>New password</label><input type="password" name="new_password" autocomplete="new-password" required></div><div class="field full"><label>Confirm new password</label><input type="password" name="confirm_password" autocomplete="new-password" required></div><button class="button button-primary">Change password</button></form></section><section class="panel span-7"><h2>Recent sign-ins</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>IP address</th><th>Result</th><th>Device</th></tr></thead><tbody><?php foreach($logins as $login):?><tr><td><?=e(formatDate($login['login_time']))?></td><td><?=e($login['ip_address'])?></td><td><span class="badge <?=e($login['status'])?>"><?=e($login['status'])?></span></td><td><?=e(mb_strimwidth($login['user_agent'],0,55,'…'))?></td></tr><?php endforeach?></tbody></table></div></section></div><?php require __DIR__.'/../includes/customer_footer.php';?>
